    AND DATE_FORMAT(CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitendDateEnd,jdbcType=VARCHAR}


    and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') >= #{dataDateStart,jdbcType=VARCHAR}


