INSERT INTO CHB_EMPLOYEE_INFO_SUB_HIS ( HIS_NO, EMPLOYEE_TYPE, EMPLOYEE_NAME, EMPLOYEE_SEX, ISSUE_PARTY_ID, IDENTIFY_NUMBER, BELONGS_BANK, BELONGS_PLACE, COMPANY_NAME, BELONGS_DEPT, POSITION, EDUCATION, ACADEMIC_DEGREE, FIRSTTIME2WORK, FIRSTTIME2FINWORK, PROFESSIONAL_TITLE, FIN_PROFESSIONAL_CRTF, FIN_TRAINING_NO, AWARDS, OFFICE_TEL, MOBILE_TEL, MAIL, REG_BUSI_TYPE, REG_EMPLOYEE_TYPE, STATUS, DEPT_CODE, ORG_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, SUMIT_SEQ, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, SEND_STATUS, STATUS_DATE, SUBMIT_TIME, REMARK, SUBMIT_FEEDBACK_MSG ) SELECT _nextIndex('EMPLOYEEINFO_SEQUENCE'), EMPLOYEE_TYPE, EMPLOYEE_NAME, EMPLOYEE_SEX, ISSUE_PARTY_ID, IDENTIFY_NUMBER, BELONGS_BANK, BELONGS_PLACE, COMPANY_NAME, BELONGS_DEPT, POSITION, EDUCATION, ACADEMIC_DEGREE, FIRSTTIME2WORK, FIRSTTIME2FINWORK, PROFESSIONAL_TITLE, FIN_PROFESSIONAL_CRTF, FIN_TRAINING_NO, AWARDS, OFFICE_TEL, MOBILE_TEL, MAIL, REG_BUSI_TYPE, REG_EMPLOYEE_TYPE, STATUS, DEPT_CODE, ORG_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, SUMIT_SEQ, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, SEND_STATUS, STATUS_DATE, SUBMIT_TIME, REMARK, SUBMIT_FEEDBACK_MSG FROM CHB_EMPLOYEE_INFO_SUB WHERE 1 =1
concat_ws('',EMPLOYEE_TYPE,IDENTIFY_NUMBER) = concat_ws('',#{regist.employeeType,jdbcType=VARCHAR},#{regist.identifyNumber,jdbcType=VARCHAR}) and SUMIT_SEQ != #{regist.sumitSeq,jdbcType=VARCHAR}
