mapper.insert:
insert into CHB_EMPLOYEE_INFO_SUB ( EMPLOYEE_TYPE, EMPLOYEE_NAME, EMPLOYEE_SEX, ISSUE_PARTY_ID, IDENTIFY_NUMBER, BELONGS_BANK, BELONGS_PLACE, COMPANY_NAME, BELONGS_DEPT, POSITION, EDUCATION, ACADEMIC_DEGREE, FIRSTTIME2WORK, FIRSTTIME2FINWORK, PROFESSIONAL_TITLE, FIN_PROFESSIONAL_CRTF, FIN_TRAINING_NO, AWARDS, OFFICE_TEL, MOBILE_TEL, MAIL, REG_BUSI_TYPE, REG_EMPLOYEE_TYPE, STATUS, DEPT_CODE, ORG_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, SUMIT_SEQ, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, SEND_STATUS, STATUS_DATE, SUBMIT_TIME, REMARK, SUBMIT_FEEDBACK_MSG ) select EMPLOYEE_TYPE, EMPLOYEE_NAME, EMPLOYEE_SEX, ISSUE_PARTY_ID, IDENTIFY_NUMBER, BELONGS_BANK, BELONGS_PLACE, COMPANY_NAME, BELONGS_DEPT, POSITION, EDUCATION, ACADEMIC_DEGREE, FIRSTTIME2WORK, FIRSTTIME2FINWORK, PROFESSIONAL_TITLE, FIN_PROFESSIONAL_CRTF, FIN_TRAINING_NO, AWARDS, OFFICE_TEL, MOBILE_TEL, MAIL, REG_BUSI_TYPE, REG_EMPLOYEE_TYPE, STATUS, DEPT_CODE, ORG_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, SUMIT_SEQ, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, SEND_STATUS, STATUS_DATE, SUBMIT_TIME, REMARK, SUBMIT_FEEDBACK_MSG from ( select HIS_NO, EMPLOYEE_TYPE, EMPLOYEE_NAME, EMPLOYEE_SEX, ISSUE_PARTY_ID, IDENTIFY_NUMBER, BELONGS_BANK, BELONGS_PLACE, COMPANY_NAME, BELONGS_DEPT, POSITION, EDUCATION, ACADEMIC_DEGREE, FIRSTTIME2WORK, FIRSTTIME2FINWORK, PROFESSIONAL_TITLE, FIN_PROFESSIONAL_CRTF, FIN_TRAINING_NO, AWARDS, OFFICE_TEL, MOBILE_TEL, MAIL, REG_BUSI_TYPE, REG_EMPLOYEE_TYPE, STATUS, DEPT_CODE, ORG_CODE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, SUMIT_SEQ, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, SEND_STATUS, STATUS_DATE, SUBMIT_TIME, REMARK, SUBMIT_FEEDBACK_MSG, rank() over (partition by EMPLOYEE_TYPE,IDENTIFY_NUMBER order by IFNULL(update_time,create_time) desc) ranknum from CHB_EMPLOYEE_INFO_SUB_HIS where 1=1
concat_ws('',#{regist.employeeType,jdbcType=VARCHAR},#{regist.identifyNumber,jdbcType=VARCHAR})
) A where ranknum = 1

mapper.delete:
DELETE FROM CHB_EMPLOYEE_INFO_SUB_HIS WHERE 1 =1 AND HIS_NO IN (SELECT A.HIS_NO FROM (SELECT HIS_NO, ROW_NUMBER() OVER(PARTITION BY EMPLOYEE_TYPE,IDENTIFY_NUMBER ORDER BY IFNULL(UPDATE_TIME,CREATE_TIME) DESC) MYRANK FROM CHB_EMPLOYEE_INFO_SUB_HIS WHERE 1=1
concat_ws('',#{regist.employeeType,jdbcType=VARCHAR},#{regist.identifyNumber,jdbcType=VARCHAR})
)A WHERE A.MYRANK=1 )
